<?php
require __DIR__.'/config.php'; require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$action=$_POST['action']??'';if(in_array($action,['published','pending','rejected'],true)){db()->prepare('UPDATE trips SET status=? WHERE id=?')->execute([$action,$id]);}elseif($action==='delete'){db()->prepare('DELETE FROM trips WHERE id=?')->execute([$id]);}header('Location: dashboard.php');exit;}
$trips=db()->query('SELECT * FROM trips ORDER BY created_at DESC')->fetchAll();
$inquiries=db()->query('SELECT i.*,t.title AS trip_title FROM inquiries i JOIN trips t ON t.id=i.trip_id ORDER BY i.created_at DESC')->fetchAll();
$counts=db()->query("SELECT status,COUNT(*) total FROM trips GROUP BY status")->fetchAll();$stats=['pending'=>0,'published'=>0,'rejected'=>0];foreach($counts as $c)$stats[$c['status']]=$c['total'];
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard — Wanderly</title><link rel="stylesheet" href="assets/style.css"></head><body class="admin-body"><aside class="admin-sidebar"><a class="brand" href="index.php">wanderly<span>.</span></a><p class="sidebar-label">WORKSPACE</p><a class="side-active" href="dashboard.php">▦ Overview</a><a href="#submissions">▤ Trip submissions</a><a href="#inquiries">✉ Inquiries</a><a href="index.php" target="_blank">↗ View website</a><a href="logout.php">↪ Sign out</a><div class="sidebar-user"><div class="avatar">W</div><div><b><?=e($_SESSION['admin_name'])?></b><small>Administrator</small></div></div></aside><main class="admin-main"><div class="admin-top"><div><span class="eyebrow">OVERVIEW</span><h1>Good morning, <?=e($_SESSION['admin_name'])?>.</h1><p>Here’s what’s happening with your travel community.</p></div><a class="btn btn-primary" href="index.php">View website ↗</a></div><div class="stats-grid"><div class="stat-card"><span>Published trips</span><strong><?=$stats['published']?></strong><small>Live on your website</small></div><div class="stat-card"><span>Pending review</span><strong><?=$stats['pending']?></strong><small>Waiting for approval</small></div><div class="stat-card"><span>Rejected</span><strong><?=$stats['rejected']?></strong><small>Not published</small></div><div class="stat-card"><span>Total inquiries</span><strong><?=count($inquiries)?></strong><small>Trip interest messages</small></div></div><section class="admin-section" id="submissions"><div class="admin-section-head"><div><h2>Trip submissions</h2><p>Review, publish, or remove community posts.</p></div><span class="pill"><?=$stats['pending']?> pending</span></div><div class="table-wrap"><table><thead><tr><th>Trip</th><th>Contributor</th><th>Price</th><th>Status</th><th>Submitted</th><th>Actions</th></tr></thead><tbody><?php foreach($trips as $t):?><tr><td><b><?=e($t['title'])?></b><small><?=e($t['destination'])?></small></td><td><?=e($t['submitted_by'])?><small><?=e($t['contact_email'])?></small></td><td>$<?=number_format((float)$t['price'],0)?></td><td><span class="status status-<?=e($t['status'])?>"><?=e(ucfirst($t['status']))?></span></td><td><?=date('M j, Y',strtotime($t['created_at']))?></td><td><div class="actions"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$t['id']?>"><select name="action" aria-label="Status"><option value="published">Publish</option><option value="pending">Pending</option><option value="rejected">Reject</option></select><button class="mini-btn">Save</button></form><form method="post" onsubmit="return confirm('Delete this trip permanently?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$t['id']?>"><button class="mini-btn danger" name="action" value="delete">Delete</button></form></div></td></tr><?php endforeach;?></tbody></table><?php if(!$trips):?><p class="empty-table">No submissions yet.</p><?php endif;?></div></section><section class="admin-section" id="inquiries"><div class="admin-section-head"><div><h2>Recent inquiries</h2><p>Messages from people interested in a trip.</p></div></div><div class="table-wrap"><table><thead><tr><th>Traveler</th><th>Trip</th><th>Message</th><th>Date</th></tr></thead><tbody><?php foreach($inquiries as $i):?><tr><td><b><?=e($i['full_name'])?></b><small><?=e($i['email'])?></small></td><td><?=e($i['trip_title'])?></td><td><?=e($i['message'])?></td><td><?=date('M j, Y',strtotime($i['created_at']))?></td></tr><?php endforeach;?></tbody></table><?php if(!$inquiries):?><p class="empty-table">No inquiries yet.</p><?php endif;?></div></section></main></body></html>
